// Captured profiles made on Chrome up to 117 carry a Windows WebGL renderer with no PCI device id:
//   ANGLE (NVIDIA, NVIDIA GeForce RTX 4070 Ti Direct3D11 vs_5_0 ps_5_0, D3D11)
// Chrome 118 and later always print "(0x%08X)" before "Direct3D11", so an engine on 156 showing the old
// shape shows a string it cannot produce (the /audit row webgl-renderer-angle-format flags it). These add
// the id real captures of the same card print. Same rules as the Node and Python SDKs and the Profile
// Manager; the table (AngleDeviceIds.g.cs) is generated by sdk/scripts/gen_angle_device_ids.py.
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;

namespace Clearcote;

internal static class AngleDeviceId
{
    private static readonly Regex NoId = new(@"^ANGLE \(([^,]+), (.+?) (Direct3D11(?:on12)? vs_\d_\d ps_\d_\d, D3D11\))$", RegexOptions.CultureInvariant);

    /// The renderer with the device id ANGLE prints for that card; unchanged when it has one already, is
    /// not a Direct3D 11 renderer, or the card is not in the table. `arch` is the capture's WebGPU
    /// architecture: it picks an id of the same chip generation for a generic name.
    public static string WithDeviceId(string renderer, string arch = "")
    {
        if (renderer.Contains("(0x")) return renderer;
        var m = NoId.Match(renderer);
        if (!m.Success) return renderer;
        string vendor = m.Groups[1].Value, name = m.Groups[2].Value, tail = m.Groups[3].Value;
        if (!AngleDeviceIds.ByArch.TryGetValue($"{vendor}|{name}|{arch}", out var id) &&
            !AngleDeviceIds.ByName.TryGetValue($"{vendor}|{name}", out id))
            return renderer;
        return $"ANGLE ({vendor}, {name} ({id}) {tail}";
    }

    /// Give every WebGL renderer in a parsed capture its device id, in place. True when it changed.
    public static bool FixCaptureRenderers(JsonObject capture)
    {
        if (capture["webgl"] is not JsonObject webgl) return false;
        var archNode = capture["webgpu"]?["high_performance"]?["info"]?["architecture"];
        var arch = archNode is JsonValue v && v.TryGetValue<string>(out var a) ? a : "";
        var changed = false;
        foreach (var ctx in new[] { "webgl1", "webgl2" })
        {
            if (webgl[ctx]?["debug"] is not JsonObject debug) continue;
            if (debug["UNMASKED_RENDERER_WEBGL"] is not JsonValue rv || !rv.TryGetValue<string>(out var r)) continue;
            var fixedR = WithDeviceId(r, arch);
            if (fixedR == r) continue;
            debug["UNMASKED_RENDERER_WEBGL"] = fixedR;
            changed = true;
        }
        return changed;
    }

    /// The capture's bytes as the engine should get them: renderers fixed, else the bytes as they were.
    public static byte[] CaptureForEngine(byte[] raw)
    {
        try
        {
            if (JsonNode.Parse(raw) is JsonObject obj && FixCaptureRenderers(obj))
                return Encoding.UTF8.GetBytes(obj.ToJsonString());
        }
        catch (JsonException)
        {
            // not JSON: handed over untouched, as before
        }
        return raw;
    }
}
